text(await tools.exec_command({cmd:`cat > /app/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="theme-color" content="#151311">
<title>Vegan ramen</title>
<style>
  * { box-sizing: border-box }
  html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; background: #151311 }
  main {
    width: 100%; height: 100%; height: 100svh; position: relative; isolation: isolate;
    overflow: hidden; display: grid; place-items: center;
    background: radial-gradient(ellipse at 49% 48%, #33291f 0%, #26221d 30%, #1b1916 58%, #121211 100%);
  }
  #scene { display: block; width: min(1070px, 105vw, 134svh); height: auto; overflow: visible; }
  #paper { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; opacity: .105; mix-blend-mode: soft-light }
  #dish, #air { will-change: transform }
  .steam { transform-box: fill-box; transform-origin: 50% 100%; animation: breathe var(--period) ease-in-out var(--delay) infinite alternate }
  .mote { animation: rise var(--period) linear var(--delay) infinite; opacity: 0 }
  .glint { animation: simmer var(--period) ease-in-out var(--delay) infinite alternate }
  @keyframes breathe {
    from { transform: translate(-3px, 2px) skewX(-2deg) scaleY(.97); opacity: .74 }
    to { transform: translate(4px,-3px) skewX(2deg) scaleY(1.06); opacity: 1 }
  }
  @keyframes rise {
    0% { transform: translate(0,0); opacity: 0 }
    22% { opacity: .45 }
    68% { opacity: .21 }
    100% { transform: translate(var(--drift),-43px); opacity: 0 }
  }
  @keyframes simmer { from { opacity: .32 } to { opacity: .94 } }
  @media (max-aspect-ratio: 4/5) { #scene { width: min(132vw, 139svh); } }
  @media (prefers-reduced-motion: reduce) {
    .steam, .mote, .glint { animation: none }
    .mote { opacity: .22 }
    #air, #dish { will-change: auto }
  }
</style>
</head>
<body>
<main>
<svg id="scene" viewBox="0 0 1000 760" role="img" aria-labelledby="scene-title scene-description" xmlns="http://www.w3.org/2000/svg">
  <title id="scene-title">A steaming bowl of vegan ramen</title>
  <desc id="scene-description">Golden noodles in amber broth with scored shiitake mushrooms, bok choy, roasted tofu, nori, and scallions. Wisps of steam curl above a red ceramic bowl painted with golden waves.</desc>
  <defs>
    <radialGradient id="warmth"><stop stop-color="#b0743e" stop-opacity=".19"/><stop offset=".53" stop-color="#a16d3f" stop-opacity=".075"/><stop offset="1" stop-color="#96633a" stop-opacity="0"/></radialGradient>
    <radialGradient id="tableLight"><stop stop-color="#96704c" stop-opacity=".32"/><stop offset=".55" stop-color="#7b6249" stop-opacity=".13"/><stop offset="1" stop-color="#73614c" stop-opacity="0"/></radialGradient>
    <radialGradient id="shade"><stop stop-color="#0a0907" stop-opacity=".98"/><stop offset=".6" stop-color="#0e0c0a" stop-opacity=".81"/><stop offset="1" stop-color="#110e0b" stop-opacity="0"/></radialGradient>
    <linearGradient id="clay" x1="0" y1=".24" x2="1" y2=".68" gradientUnits="objectBoundingBox">
      <stop stop-color="#8d3b28"/><stop offset=".13" stop-color="#ba6140"/><stop offset=".32" stop-color="#bf6240"/><stop offset=".57" stop-color="#a64b32"/><stop offset=".82" stop-color="#773423"/><stop offset="1" stop-color="#3f251f"/>
    </linearGradient>
    <linearGradient id="kiln" x1="0" x2=".1" y1="0" y2="1"><stop stop-color="#f49955" stop-opacity=".12"/><stop offset=".52" stop-color="#561c1b" stop-opacity="0"/><stop offset=".84" stop-color="#3a201c" stop-opacity=".22"/><stop offset="1" stop-color="#291e19" stop-opacity=".62"/></linearGradient>
    <linearGradient id="lip" x1="0" y1=".1" x2=".91" y2="1"><stop stop-color="#f2cb92"/><stop offset=".25" stop-color="#d79761"/><stop offset=".48" stop-color="#ae6844"/><stop offset=".66" stop-color="#edb47b"/><stop offset="1" stop-color="#78462f"/></linearGradient>
    <linearGradient id="inner" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#4a291e"/><stop offset=".27" stop-color="#965e3b"/><stop offset=".6" stop-color="#c58f59"/><stop offset="1" stop-color="#805239"/></linearGradient>
    <linearGradient id="footPaint"><stop stop-color="#553325"/><stop offset=".17" stop-color="#926047"/><stop offset=".47" stop-color="#744632"/><stop offset="1" stop-color="#372921"/></linearGradient>
    <radialGradient id="broth" cx=".43" cy=".42" r=".72"><stop stop-color="#e5a044"/><stop offset=".38" stop-color="#d28b36"/><stop offset=".71" stop-color="#bb6c29"/><stop offset=".9" stop-color="#9d5124"/><stop offset="1" stop-color="#6a381d"/></radialGradient>
    <linearGradient id="seaweed" x1=".1" y1="0" x2=".8" y2="1"><stop stop-color="#536044"/><stop offset=".19" stop-color="#394b37"/><stop offset=".44" stop-color="#2d3f31"/><stop offset=".76" stop-color="#27372c"/><stop offset="1" stop-color="#1d3027"/></linearGradient>
    <radialGradient id="cap" cx=".36" cy=".25" r=".79"><stop stop-color="#cb8d52"/><stop offset=".26" stop-color="#b87842"/><stop offset=".63" stop-color="#98542f"/><stop offset=".86" stop-color="#743d26"/><stop offset="1" stop-color="#4b3023"/></radialGradient>
    <linearGradient id="flesh" x1="0" y1="0" x2=".25" y2="1"><stop stop-color="#b98146"/><stop offset=".5" stop-color="#f6d295"/><stop offset="1" stop-color="#dba96f"/></linearGradient>
    <linearGradient id="leaf" x1=".05" y1="0" x2=".95" y2=".65"><stop stop-color="#344c2e"/><stop offset=".32" stop-color="#60763d"/><stop offset=".51" stop-color="#809249"/><stop offset=".69" stop-color="#4c6835"/><stop offset="1" stop-color="#2c4d30"/></linearGradient>
    <linearGradient id="stalk" x1=".1" y1=".9" x2=".82" y2=".05"><stop stop-color="#ead392"/><stop offset=".27" stop-color="#c4c57b"/><stop offset=".58" stop-color="#91a359"/><stop offset="1" stop-color="#607f40"/></linearGradient>
    <linearGradient id="tofuTop" x1=".1" y1="0" x2=".9" y2="1"><stop stop-color="#f9d69a"/><stop offset=".52" stop-color="#e5b770"/><stop offset="1" stop-color="#c68f4e"/></linearGradient>
    <linearGradient id="tofuFront" x1=".12" y1="0" x2=".8" y2="1"><stop stop-color="#eac083"/><stop offset=".5" stop-color="#c58e51"/><stop offset="1" stop-color="#ba763d"/></linearGradient>
    <linearGradient id="tofuSide" x1="0" y1="0" x2="1" y2=".4"><stop stop-color="#b27b40"/><stop offset="1" stop-color="#936033"/></linearGradient>
    <linearGradient id="vapor" x1="0" y1="1" x2="0" y2="0"><stop stop-color="#eee0b7" stop-opacity=".04"/><stop offset=".25" stop-color="#ead8b2" stop-opacity=".31"/><stop offset=".57" stop-color="#e2d4b7" stop-opacity=".26"/><stop offset=".83" stop-color="#d8c7a9" stop-opacity=".13"/><stop offset="1" stop-color="#d8c7a9" stop-opacity="0"/></linearGradient>
    <filter id="haze" x="-.45" y="-.2" width="1.9" height="1.4"><feGaussianBlur stdDeviation="3.6"/></filter>
    <filter id="mist" x="-.45" y="-.2" width="1.9" height="1.4"><feGaussianBlur stdDeviation="1.25"/></filter>
    <filter id="grain" x="0" y="0" width="100%" height="100%"><feTurbulence type="fractalNoise" baseFrequency=".76" numOctaves="3" stitchTiles="stitch"/></filter>
    <pattern id="tooth" width="147" height="147" patternUnits="userSpaceOnUse"><rect width="147" height="147" filter="url(#grain)" opacity=".52"/></pattern>
    <clipPath id="soupClip"><ellipse cx="500" cy="398" rx="334" ry="94"/></clipPath>
    <clipPath id="capClip"><path d="M-63 6C-64-9-44-32-19-39C7-47 37-38 54-19C66-6 69 7 62 16C49 30 17 35-13 32C-39 29-61 20-63 6Z"/></clipPath>
  </defs>
  <ellipse cx="493" cy="347" rx="417" ry="318" fill="url(#warmth)"/>
  <g id="floor">
    <ellipse cx="492" cy="659" rx="445" ry="92" fill="url(#tableLight)"/>
    <ellipse cx="504" cy="669" rx="341" ry="53" fill="url(#shade)" opacity=".86"/>
    <ellipse cx="506" cy="670" rx="181" ry="23" fill="url(#shade)"/>
  </g>
  <g id="air"></g>
  <g id="dish"></g>
</svg>
<svg id="paper" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><rect width="100%" height="100%" fill="url(#tooth)"/></svg>
</main>
<script>
(() => {
  'use strict';
  const svg = document.querySelector('#scene');
  const defs = svg.querySelector('defs');
  const dish = document.querySelector('#dish');
  const air = document.querySelector('#air');
  let seed = 971216;
  function random(min = 0, max = 1) {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return min + seed / 4294967296 * (max - min);
  }
  const pick = values => values[Math.floor(random(0, values.length))];
  const f = value => +value.toFixed(2);
  const pair = (x,y) => f(x)+' '+f(y);
  const points = list => list.map(p => pair(...p)).join(' ');
  const path = (d,fill,extra='') => '<path d="'+d+'" fill="'+fill+'" '+extra+'/>';
  const line = (d,color,width,opacity=1,extra='') => path(d,'none','stroke="'+color+'" stroke-width="'+f(width)+'" stroke-opacity="'+f(opacity)+'" stroke-linecap="round" stroke-linejoin="round" '+extra);
  const ellipse = (x,y,rx,ry,fill,extra='') => '<ellipse cx="'+f(x)+'" cy="'+f(y)+'" rx="'+f(rx)+'" ry="'+f(ry)+'" fill="'+fill+'" '+extra+'/>';
  const group = (content,attrs='') => '<g '+attrs+'>'+content+'</g>';
  const alpha = v => 'opacity="'+f(v)+'"';
  const outline = (color,width) => 'stroke="'+color+'" stroke-width="'+width+'" stroke-linejoin="round"';
  const tex = (d,opacity) => path(d,'url(#tooth)',alpha(opacity)+' style="mix-blend-mode:soft-light"');
  const poly = pts => 'M'+points(pts)+'Z';
  function curve(pts) { return 'M'+points(pts); }
  function clip(id,d) {
    defs.insertAdjacentHTML('beforeend','<clipPath id="'+id+'">'+path(d,'white')+'</clipPath>');
    return 'clip-path="url(#'+id+')"';
  }

  // Project the painted decoration onto the curved face of the pottery.
  function surface(angle,t) {
    const radius = 349-211*(.18*t+.82*t*t);
    return [500+radius*Math.sin(angle),393+244*t+(103-70*t)*Math.cos(angle)];
  }
  function row(t, start=-Math.PI/2, end=Math.PI/2, n=84) {
    return Array.from({length:n+1},(_,i)=>surface(start+(end-start)*i/n,t));
  }
  function side(angle,reverse=false) {
    return Array.from({length:37},(_,i)=>surface(angle,reverse?1-i/36:i/36));
  }
  const bowlShape = poly([...row(0),...side(Math.PI/2),...row(1).reverse(),...side(-Math.PI/2,true)]);
  const bodyClip = clip('bodyClip',bowlShape);
  const bandClip = clip('bandClip',poly([...row(.103),...row(.365).reverse()]));
  let art = '';
  const foot='M367 631Q371 650 374 660C409 687 565 694 623 665L634 635Z';
  art += path(foot,'url(#footPaint)',outline('#39291f',2));
  art += line('M377 659C424 682 570 685 622 661','#bb8861',2.7,.63);
  art += tex(foot,.6);
  art += path(bowlShape,'url(#clay)',outline('#533526',2.8));
  art += path(bowlShape,'url(#kiln)');
  let glaze='';
  for(let i=0;i<320;i++) {
    const t=random(.015,.985), a=random(-1.57,1.57);
    glaze+=line(curve(row(t,a,Math.min(1.57,a+random(.011,.32)),10)),pick(['#edb080','#ee9768','#552e25','#613323']),random(.45,1.65),random(.06,.24));
  }
  for(let i=0;i<850;i++) {
    const p=surface(random(-1.56,1.56),random(.015,.99));
    glaze+=ellipse(...p,random(.3,1.2),random(.25,.72),pick(['#643925','#edba8d']),alpha(random(.16,.44)));
  }
  art+=group(glaze,bodyClip);
  let pattern='';
  const spacing=.224;
  // Overlapping fans, applied in rows as on a hand-painted seigaiha bowl.
  for(let r=0;r<4;r++) {
    const base=.157+r*.105;
    for(let j=-8;j<9;j++) {
      const a=j*spacing+(r%2)*spacing/2;
      for(let ring=1;ring<=4;ring++) {
        const arc=[];
        for(let k=0;k<=22;k++) {
          const phase=Math.PI*k/22, angle=a+Math.cos(phase)*spacing*.5*ring/4;
          arc.push(surface(Math.min(1.572,Math.max(-1.572,angle)),base-Math.sin(phase)*.142*ring/4));
        }
        if(a>-1.72 && a<1.72) pattern+=line(curve(arc),'#ebc588',ring===4?2.05:1.45,random(.69,.91));
      }
    }
  }
  art+=group(pattern,bandClip);
  for(const [t,c,w,o] of [[.065,'#653521',3,.8],[.082,'#edba81',2.3,.92],[.102,'#e4b179',1.1,.9],[.368,'#eec28b',2.3,.95],[.396,'#dda570',1.5,.9],[.845,'#d18253',1.2,.38],[.926,'#602f22',2,.56],[.957,'#cc895c',1.4,.52]]) {
    art+=line(curve(row(t)),c,w,o);
  }
  art+=tex(bowlShape,.58);
  art+=ellipse(500,393,349,103,'url(#lip)',outline('#563828',1.8));
  art+=ellipse(500,392,340.5,96.4,'url(#inner)',outline('#f3c690',1.3));
  art+=ellipse(500,398,334,94,'url(#broth)');

  // Small slicks of oil and interrupted reflections break up the surface of the broth.
  let soup='';
  for(let i=0;i<380;i++) {
    const a=random(0,Math.PI*2),r=Math.sqrt(random());
    const x=500+Math.cos(a)*r*333,y=398+Math.sin(a)*r*94;
    const size=random(.55,4.5);
    soup+=ellipse(x,y,size,size*random(.25,.56),pick(['#f5c565','#f4b852','#e4a044','#8d4624','#ad5724']),alpha(random(.28,.79)));
  }
  for(let i=0;i<105;i++) {
    const x=random(162,820), y=random(310,493), w=random(4,37);
    soup+=line('M'+pair(x,y)+'q'+pair(w*.42,random(-4,2))+' '+pair(w,random(-2,4)),pick(['#fbd28a','#f6b655','#93471e','#ec9e39']),random(.8,2.7),random(.34,.79));
  }
  function ripple(x,y,rx,ry,a,b) {
    return 'M'+pair(x+rx*Math.cos(a),y+ry*Math.sin(a))+'A'+pair(rx,ry)+' 0 '+(b-a>Math.PI?1:0)+' 1 '+pair(x+rx*Math.cos(b),y+ry*Math.sin(b));
  }
  for(let i=0;i<37;i++){
    const x=random(190,814),y=random(328,490),a=random(0,3.2),b=a+random(1,3.2);
    soup+=line(ripple(x,y,random(3,16),random(1.6,4.3),a,b),'#ffcf78',random(.75,1.8),.68);
  }
  art+=group(soup,'clip-path="url(#soupClip)"');

  function nori(id,corners) {
    const border=[];
    for(let e=0;e<4;e++) {
      const a=corners[e],b=corners[(e+1)%4],pieces=Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])/4);
      for(let n=0;n<pieces;n++) border.push([a[0]+(b[0]-a[0])*n/pieces+random(-1.7,1.7),a[1]+(b[1]-a[1])*n/pieces+random(-1.5,1.5)]);
    }
    const d=poly(border), c=clip(id,d);
    const xs=corners.map(p=>p[0]),ys=corners.map(p=>p[1]);
    let flecks='';
    for(let i=0;i<1800;i++) {
      const x=random(Math.min(...xs),Math.max(...xs)),y=random(Math.min(...ys),Math.max(...ys)),w=random(.5,4.7),h=random(.4,2.2);
      flecks+=path('M'+pair(x,y)+'l'+pair(w*.44,-h)+' '+pair(w*.56,h*.35)+' '+pair(-w*.24,h)+'Z',pick(['#8e9770','#536548','#758361','#172c25','#bbc19a']),alpha(random(.16,.61)));
    }
    for(let i=0;i<48;i++) {
      const x=random(Math.min(...xs),Math.max(...xs)), y=random(Math.min(...ys),Math.max(...ys));
      flecks+=line('M'+pair(x,y)+'q-2 -4 0 -8t-1 -10',pick(['#95a07c','#1b3028']),random(.5,1.5),.37);
    }
    return path(d,'url(#seaweed)',outline('#263226',1.7))+group(flecks,c)+line(curve(border.slice(0,Math.ceil(Math.hypot(corners[1][0]-corners[0][0],corners[1][1]-corners[0][1])/4))),'#a4a77a',1.7,.72)+tex(d,.65);
  }
  art+=nori('noriRear',[[291,234],[392,219],[412,331],[318,351]]);
  art+=nori('noriFront',[[211,260],[325,232],[360,343],[248,369]]);

  function leaf(id,x,y,rotation,sx,sy) {
    const d='M-9 0C-16-17-18-39-23-54C-30-66-37-74-32-85C-32-90-41-95-35-105C-42-118-34-124-37-132C-38-144-30-148-25-148C-25-158-17-166-8-162Q-1-174 7-165C17-169 22-158 23-152C35-154 39-144 34-135C43-128 37-119 40-114C45-105 34-100 34-94C38-84 27-77 26-70C24-56 15-45 14-31C12-13 16-4 9 1Q0 6-9 0Z';
    const c=clip(id,d);
    let greens=path(d,'url(#leaf)',outline('#344b2c',1.6));
    let veins='';
    for(let s of [-1,1]) {
      for(let i=0;i<11;i++) {
        const y0=-44-i*10.1, size=17+16*Math.sin(i*.26), end=y0-random(11,21);
        const x0=Math.sin(y0/31)*3;
        const v='M'+pair(x0,y0)+'Q'+pair(s*size*.54,y0-4)+' '+pair(s*size*.73,end+4)+'T'+pair(s*(size+3),end-3);
        veins+=line(v,'#253f2c',3.3,.56);
        veins+=line(v,'#a3ad69',1.35,.81,'transform="translate(-.5 -1)"');
        for(let j=0;j<3;j++){
          const px=s*size*(.38+j*.19),py=y0-3-j*3.8;
          veins+=line('M'+pair(px,py)+'q'+pair(s*2,-3)+' '+pair(s*random(4,9),-8),'#bbbd76',.75,.52);
        }
      }
    }
    for(let i=0;i<220;i++){
      const px=random(-37,39),py=random(-165,-43);
      veins+=line('M'+pair(px,py)+'l'+pair(random(-2,2),random(-2.5,-.5)),pick(['#d7cb87','#2b4d31']),random(.5,1.05),random(.15,.49));
    }
    greens+=group(veins,c);
    greens+=path('M-9 1C-19-12-18-29-16-44C-13-59-8-68-6-79C-1-96 2-117 1-146C6-121 4-102 4-83C6-66 10-57 12-43C16-24 19-8 10 1Q0 7-9 1Z','url(#stalk)',outline('#6c844a',1));
    for(let j=0;j<7;j++) {
      const xx=-12+j*4;
      greens+=line('M'+pair(xx*.6,-2)+'Q'+pair(xx*1.26,-22)+' '+pair(xx*.83,-45)+'T'+pair(xx*.16+1,-88-Math.abs(3-j)*-7),pick(['#e6d89a','#708d4c','#b2bd74']),random(.7,1.35),.78);
    }
    return group(greens+tex(d,.6),'transform="translate('+pair(x,y)+') rotate('+rotation+') scale('+pair(sx,sy)+')"');
  }
  art+=leaf('greens1',554,372,-6,.77,.68);
  art+=leaf('greens2',553,378,16,.94,.95);
  art+=leaf('greens3',557,384,39,1.0,1.09);
  art+=leaf('greens4',563,386,61,.87,1);
  art+=leaf('greens5',566,388,79,.68,.77);

  function mushroom(x,y,rotation,scale) {
    const cap='M-63 6C-64-9-44-32-19-39C7-47 37-38 54-19C66-6 69 7 62 16C49 30 17 35-13 32C-39 29-61 20-63 6Z';
    let m=path('M-63 4C-58 38-10 49 33 36Q63 30 65 12Q9 23-63 4Z','url(#flesh)',outline('#643c26',1.6));
    for(let i=0;i<34;i++){
      const a=i/33*Math.PI;
      const px=63*Math.cos(a),py=13+25*Math.sin(a);
      m+=line('M'+pair(px,py)+'q'+pair(-px*.1,-1)+' '+pair(-px*.16,-5.8),'#996b3e',1.4,.74);
    }
    m+=path(cap,'url(#cap)',outline('#643a25',2));
    let skin='';
    for(let i=0;i<550;i++){
      const px=random(-64,66),py=random(-42,33);
      const d='M'+pair(px,py)+'q'+pair(random(.2,1.7),-.8)+' '+pair(random(1.4,3.4),random(-1,1.2));
      skin+=line(d,pick(['#5a3526','#e6af72','#f2c88b','#a46337']),random(.5,1.5),random(.17,.58));
    }
    m+=group(skin,'clip-path="url(#capClip)"');
    m+=line('M-54-6Q-40-29-16-33M-8-35Q1-37 10-35','#e8af72',1.6,.8);
    // A shallow flower cut exposes the pale flesh under the browned skin.
    m+=path('M-39-21Q-20-18-5-12Q-4-22-9-32Q2-26 6-14Q19-22 36-22Q25-14 15-7Q29-3 42 9Q23 4 7 1Q5 12-3 22Q-6 10-6-2Q-22 5-40 6Q-28-3-16-8Q-32-14-39-21Z','#704128');
    m+=path('M-38-20Q-20-16-3-11Q-4-23-9-32Q2-25 6-12Q22-21 36-22Q24-12 11-6Q29-1 42 9Q23 2 4-1Q4 12-3 22Q-4 9-4-4Q-23 4-40 6Q-27-1-12-8Q-28-13-38-20Z','url(#flesh)');
    m+=line('M-35-19Q-18-11-8-9M-2 18L0-6 31-20','#f6d49a',1.3,.89);
    return group(m+tex(cap,.56),'transform="translate('+pair(x,y)+') rotate('+rotation+') scale('+scale+')"');
  }
  art+=mushroom(452,308,14,.91);
  art+=mushroom(346,343,-17,1.02);

  // Each strand follows its own cubic spline through a loosely folded bundle.
  const noodleColors=['#edbd66','#ebbb63','#f0c773','#e3ae56','#e9ba69','#f1c776'];
  function noodleBundle(control,count,space,width) {
    let strands='';
    for(let i=0;i<count;i++) {
