    })()\`);
    assert.ok(bounds.minX>0 && bounds.maxX<width && bounds.minY>0 && bounds.maxY<height && !bounds.overflow,JSON.stringify(bounds));
    console.log(width+'x'+height+' — bowl and steam fit');
  }
  await call('Emulation.setDeviceMetricsOverride',{width:1440,height:900,deviceScaleFactor:1,mobile:false});
  const location=await evalPage('(()=>{const p=new DOMPoint(786,399).matrixTransform(document.querySelector("#scene").getScreenCTM());return {x:p.x,y:p.y}})()');
  await call('Input.dispatchMouseEvent',{type:'mouseMoved',...location});
